# The Phase 1 acceptance gate (`spec/08-decisions.md` D-9): for every corpus
# entry, ExTLA and TLC must agree on the number of distinct reachable states,
# whether each invariant holds, and the length of the shortest counterexample
# where one exists.
#
# `expected.json` is TLC's answer, generated by `bin/tlc-expected` and checked
# against a live TLC run by CI — so these tests compare ExTLA to an oracle, not
# to its own output from last week. That distinction is the whole point of
# landing the corpus before the checker: a checker that explores 15 of 16 states
# reports "no violation found" in exactly the same words as one that explores
# all 16.
#
# The comparisons themselves are in `TLA.DifferentialCase`; this file is the
# corpus table. Each entry names its ExTLA spec module and the constants TLC was
# run with — `die_hard` has none, since the jugs are in the module.
#
# `names` maps a TLC invariant to its ExTLA counterpart where underscoring is
# not enough. TLA+ modules prefix by convention (`TPTypeOK`), and ExTLA's
# implicit type invariant is always `:type_ok`, so the mapping is stated per
# entry rather than guessed — which also means an invariant that goes missing
# from the DSL spec is reported instead of silently skipped.
entries = [
  %{name: "die_hard", module: TLA.Differential.DieHard, constants: %{}, names: %{}},
  # The smallest entry, and the only one whose subject is a declaration KIND rather than an
  # algorithm: `action_property` is the one Layer 2 feature the oracle had never seen, which
  # is how #112 survived for as long as the feature had existed. Its `compact` empties the
  # log, so the offending step's post-state IS the initial state — the decoy that makes a
  # counterexample built from the wrong end of the step come back a different LENGTH rather
  # than merely a different path. See `AuditLog.tla`.
  %{
    name: "audit_log",
    module: TLA.Differential.AuditLog,
    constants: %{max_entries: 2},
    names: %{}
  },
  %{
    name: "two_phase_commit",
    module: TLA.Differential.TwoPhaseCommit,
    constants: %{rms: MapSet.new([:r1, :r2, :r3])},
    names: %{"TPTypeOK" => :type_ok}
  },
  %{
    name: "distributed_lock",
    module: TLA.Differential.DistributedLock,
    constants: %{
      processes: MapSet.new([:p1, :p2]),
      resources: MapSet.new([:r1, :r2])
    },
    names: %{}
  },
  %{
    name: "raft_election",
    module: TLA.Differential.RaftElection,
    constants: %{servers: MapSet.new([:s1, :s2, :s3]), max_term: 2},
    names: %{}
  },
  # The only entry whose subject is the VOCABULARY rather than an algorithm (#319, for
  # #183). Every set-theoretic operator in it is called the way an author writes one --
  # unqualified, in an action body -- so the oracle is what says `exists?(powerset(s), ...)`
  # means `\E q \in SUBSET S : ...` and not merely that it returns something.
  %{
    name: "set_vocabulary",
    module: TLA.Differential.SetVocabulary,
    constants: %{nodes: MapSet.new([:n1, :n2, :n3])},
    names: %{}
  },
  %{
    name: "paxos",
    module: TLA.Differential.Paxos,
    constants: %{
      acceptors: MapSet.new([:a1, :a2, :a3]),
      values: MapSet.new([:v1, :v2]),
      max_ballot: 1,
      quorums:
        MapSet.new([
          MapSet.new([:a1, :a2]),
          MapSet.new([:a1, :a3]),
          MapSet.new([:a2, :a3]),
          MapSet.new([:a1, :a2, :a3])
        ])
    },
    names: %{}
  },
  %{
    name: "bounded_buffer",
    module: TLA.Differential.BoundedBuffer,
    constants: %{
      producers: MapSet.new([:p1, :p2]),
      consumers: MapSet.new([:c1, :c2]),
      buffer_size: 3,
      max_items: 6
    },
    names: %{}
  }
]

for entry <- entries do
  defmodule Module.concat(TLA.DifferentialTest, Macro.camelize(entry.name)) do
    use TLA.DifferentialCase, entry: entry
  end
end

defmodule TLA.DifferentialTest.DeclarationKinds do
  @moduledoc """
  A claim about the corpus as a whole rather than about any one entry: **every kind of
  declaration the DSL has is put to TLC somewhere** (#114).

  It exists because an absence is invisible by construction. `action_property` was a
  first-class declaration with its own compile path, its own runtime check and its own
  counterexample shape, and no corpus entry had ever asked TLC about one — which left no
  failing test, no line in a golden and nothing in any diff. #112 lived there for as long
  as the feature had existed, and was found by someone happening to look. #75 and #90 were
  found the same way.

  Nothing here checks that the checker is *right*; the per-entry comparisons do that. This
  checks that each kind is inside the set of things being checked at all, which is the one
  question those comparisons cannot ask about themselves.
  """
  use ExUnit.Case, async: true

  @entries entries
  @corpus Path.expand(".", __DIR__)

  # The kinds this test knows how to look for, kept beside the `exercised?/3` clauses and
  # compared against the DSL's own enumeration below. A hand-written copy of that
  # enumeration would pass on the day a sixth kind was added, which is the exact day it
  # needs to fail.
  @routed [:action, :invariant, :temporal, :action_property, :terminal]

  test "there is a stated route to TLC for every declaration kind the DSL has" do
    declared = MapSet.new(TLA.Spec.Hash.kinds())
    routed = MapSet.new(@routed)

    assert MapSet.equal?(declared, routed), """
    The DSL and this test disagree about which declaration kinds exist.

      only in TLA.Spec.Hash.kinds/0: #{inspect(Enum.sort(MapSet.difference(declared, routed)))}
      only in @routed:               #{inspect(Enum.sort(MapSet.difference(routed, declared)))}

    A kind in the first list is a declaration the differential corpus has no oracle for.
    That is the state `action_property` was in until #114, and #112 is what it cost: the
    counterexample was built from the wrong end of the step for as long as the feature had
    existed, and nothing could notice, because D-9's corpus — the project's acceptance
    criterion — had never asked TLC about one.

    Add an `exercised?/3` clause saying how the kind reaches TLC's recorded answer, and add
    it to @routed. If there is no such route, that is the finding: the kind has no oracle.
    """
  end

  # The enumeration above is a hand-written list; `bin/tlc-expected` enumerates the corpus
  # directory independently, and nothing compared the two (#174). Deleting `die_hard` and
  # `raft_election` — between them EVERY violation in the corpus — took this suite from 104
  # passed to 80 passed, exit 0, removing the only violated-invariant comparison, the only
  # violated-temporal comparison, and both independent-oracle cross-checks. `tlc-expected
  # --check` stayed green because it verifies whatever directories remain.
  #
  # So the list is now derived-and-compared rather than trusted, and it fails BOTH ways: a
  # directory nobody runs is as much a finding as an entry with no directory.
  test "the entry list and the corpus directory are the same set" do
    on_disk =
      @corpus
      |> File.ls!()
      |> Enum.filter(&File.dir?(Path.join(@corpus, &1)))
      |> MapSet.new()

    listed = MapSet.new(@entries, & &1.name)

    assert MapSet.equal?(on_disk, listed), """
    The corpus directory and this file's entry list disagree.

      on disk, not run:     #{inspect(Enum.sort(MapSet.difference(on_disk, listed)))}
      listed, not on disk:  #{inspect(Enum.sort(MapSet.difference(listed, on_disk)))}

    The first list is the dangerous one: those models are regenerated and verified against
    TLC by `bin/tlc-expected --check`, and compared to ExTLA by nothing. Removing an entry
    from the list above does not fail anything — the suite simply gets smaller.

    Add the entry, or delete the directory.
    """
  end

  # The list being complete is not the same as the corpus still containing the comparisons
  # that make it evidence. Four of the seven comparison classes have exactly ONE instance:
  # one violated invariant, one violated temporal, one violated action property. The test
  # above would not notice the last one going away, because the entry would still be listed
  # and still be compared — for the verdicts it has left.
  #
  # D-9 makes agreement with TLC the acceptance gate, and a corpus where TLC never refutes
  # anything agrees with a checker that answers "holds" to everything.
  test "the corpus still contains TLC's refutations" do
    refuting =
      Enum.flat_map(@entries, fn entry ->
        expected =
          [@corpus, entry.name, "expected.json"]
          |> Path.join()
          |> File.read!()
          |> Jason.decode!()

        for section <- ["invariants", "properties"],
            {declaration, verdict} <- Map.get(expected, section) || %{},
            refuted?(verdict),
            do: {entry.name, section, declaration}
      end)

    invariants = Enum.filter(refuting, fn {_e, section, _d} -> section == "invariants" end)
    properties = Enum.filter(refuting, fn {_e, section, _d} -> section == "properties" end)
    entries = refuting |> Enum.map(&elem(&1, 0)) |> Enum.uniq()

    assert invariants != [], refutation_message("invariant", refuting)
    assert properties != [], refutation_message("property", refuting)

    # Today: die_hard (an invariant), raft_election (a temporal), audit_log (an action
    # property). Each carries exactly one, so losing any entry loses a whole comparison
    # class — which is what made deleting two of them cost 24 tests and no failure.
    assert length(entries) >= 3, refutation_message("third distinct", refuting)
  end

  defp refuted?("violated"), do: true
  defp refuted?(%{"violated_at" => _}), do: true
  defp refuted?(_), do: false

  defp refutation_message(what, refuting) do
    """
    The corpus no longer records enough of TLC's refutations (missing: #{what}).

    Refutations found:
    #{Enum.map_join(refuting, "\n", fn {e, s, d} -> "  #{e}: #{s}.#{d}" end)}

    A corpus in which TLC never refutes anything agrees with a checker that answers "holds"
    to everything, and D-9 makes that agreement the project's acceptance criterion. Four of
    the seven comparison classes have exactly one instance, so removing one entry can remove
    a whole class silently.

    Restore the entry, or add one TLC refutes.
    """
  end

  test "every declaration kind is put to TLC by some corpus entry" do
    loaded =
      Enum.map(@entries, fn entry ->
        expected =
          [@corpus, entry.name, "expected.json"]
          |> Path.join()
          |> File.read!()
          |> Jason.decode!()

        {entry, TLA.Spec.Compiled.from_module(entry.module), expected}
      end)

    # `@routed` rather than `TLA.Spec.Hash.kinds/0`: the test above owns the claim that the
    # two agree, and iterating the DSL's list here would blow up with a FunctionClauseError
    # on a kind that has no clause instead of leaving that failure where its message is.
    for kind <- @routed do
      covering =
        for {entry, spec, expected} <- loaded,
            exercised?(kind, spec, expected),
            do: entry.name

      assert covering != [], """
      No corpus entry puts `#{kind}` to TLC.

      Declaring one somewhere is not enough — `distributed_lock` declared
      `action_property :lock_not_stolen` from the day it was written, `DistributedLock.tla`
      had no counterpart, and every gate in the project passed for the entry's whole life.
      The entry has to reach TLC's recorded answer in `expected.json`.

      See `test/differential/README.md` §Writing an entry, and `audit_log` for the smallest
      one there is — three states, written for this corpus rather than translated into it,
      because what it holds the checker to is a declaration kind and not an algorithm.
      """
    end
  end

  # How each kind reaches TLC's oracle. Four of the five have a per-item verdict recorded in
  # `expected.json`; `:action` is the one that does not, and that is a fact about TLC rather
  # than a gap here — TLC has no per-action report. What it has instead is the state count
  # and the search depth, which are a function of the transition relation the actions ARE,
  # and which every entry compares. So the clause is weak-looking and honest: an entry with
  # a wrong action does not agree with TLC on `distinct_states`.
  defp exercised?(:action, spec, expected),
    do: spec.actions != [] and is_integer(expected["distinct_states"])

  defp exercised?(:invariant, spec, expected),
    do: spec.invariants != [] and expected["invariants"] not in [nil, %{}]

  # `properties` holds both temporal and action properties, because it records the .cfg
  # section they came from; `properties_of_kind/4` splits them by which list the name is
  # declared in on the ExTLA side. It raises on a name that is in neither, which is the
  # right behaviour here too — a fixture naming a property the spec does not declare is a
  # finding, not something to return `false` for.
  defp exercised?(kind, spec, expected) when kind in [:temporal, :action_property] do
    TLA.DifferentialCase.properties_of_kind(spec, expected, %{names: %{}}, kind) != []
  end

  # A `terminal` is compared through `deadlock`: TLC calls any successor-less state a
  # deadlock, ExTLA reports one only where no `terminal` admits it, and the two are held to
  # each other by "stops where TLC stops, and every stuck state was declared". An entry that
  # declares a terminal and whose TLC run never deadlocked would not have exercised it.
  defp exercised?(:terminal, spec, expected),
    do: spec.terminals != [] and expected["deadlock"] == true
end
